body.script:
           (function() {
                let liveSessionId = null;
                let livePolling = null;
                let appointmentId = null;

                function checkActiveAppointment() {
                    fetch('/clinic/patient/active-appointment')
                        .then(r => r.json())
                        .then(data => {
                            if (data.appointment_id) {
                                appointmentId = data.appointment_id;
                                document.getElementById('live-chat-icon').style.display = 'flex';
                                startLiveChatSession();
                            }
                        })
                        .catch(e => console.log('No active appointment'));
                }

                function startLiveChatSession() {
                    fetch('/clinic/chat/start', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ appointment_id: appointmentId })
                    })
                    .then(r => r.json())
                    .then(data => {
                        if (data.session_id) {
                           liveSessionId = data.session_id;
                        }
                    });
                }

                function loadLiveMessages() {
                    if (!liveSessionId) return;
                    fetch(`/clinic/chat/history?session_id=${liveSessionId}`)
                        .then(r => r.json())
                        .then(data => {
                            if (data.messages && data.messages.length) {
                                const container = document.getElementById('live-chat-messages');
                                container.innerHTML = '';
                                data.messages.forEach(msg => {
                                    const isUser = msg.from_role === 'patient';
                                    const div = document.createElement('div');
                                    div.style.cssText = `margin-bottom:10px; text-align:${isUser ? 'right' : 'left'};`;
                                    div.innerHTML = `
${escapeHtml(msg.content)}`;
                                    container.appendChild(div);
                                });
                                container.scrollTop = container.scrollHeight;
                            }
                        });
                }

                function sendLiveMessage() {
                    const input = document.getElementById('live-chat-input');
                    const msg = input.value.trim();
                    if (!msg || !liveSessionId) return;
                    input.value = '';

                    fetch('/clinic/chat/send', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            session_id: liveSessionId,
                            message: msg,
                            from_role: 'patient'
                        })
                    }).then(() => loadLiveMessages());
                }

                function escapeHtml(text) {
                    const div = document.createElement('div');
                    div.textContent = text;
                    return div.innerHTML;
                }

                document.getElementById('live-chat-icon')?.addEventListener('click', () => {
                    const win = document.getElementById('live-chat-window');
                    win.style.display = win.style.display === 'flex' ? 'none' : 'flex';
                    if (win.style.display === 'flex') {
                        loadLiveMessages();
                        if (livePolling) clearInterval(livePolling);
                        livePolling = setInterval(loadLiveMessages, 5000);
                    } else if (livePolling) {
                        clearInterval(livePolling);
                    }
                });

                document.getElementById('close-live-chat')?.addEventListener('click', () => {
                    document.getElementById('live-chat-window').style.display = 'none';
                    if (livePolling) clearInterval(livePolling);
                });

                document.getElementById('live-chat-send')?.addEventListener('click', sendLiveMessage);
                document.getElementById('live-chat-input')?.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') sendLiveMessage();
                });

                document.getElementById('live-chat-input')?.addEventListener('keypress', (e) => {
                    if (e.key === 'Enter') sendLiveMessage();
                });

                checkActiveAppointment();
            })();

document.addEventListener("DOMContentLoaded", function () {

    /* ================= DOCTOR FILTER (SAFE) ================= */

    const specializationSelect = document.querySelector("[name='specialization_id']");
    const doctorSelect = document.getElementById("doctor_select");
    const availabilityInfo = document.getElementById("availability_info");

    if (specializationSelect && doctorSelect) {

        for (let option of doctorSelect.options) {
            if (option.value !== "") {
                option.style.display = "none";
            }
        }

        specializationSelect.addEventListener("change", function () {

            const selectedSpec = this.value;

            for (let option of doctorSelect.options) {

                if (option.value === "") continue;

                option.style.display =
                    (option.dataset.spec === selectedSpec)
                    ? "block"
                    : "none";
            }

            doctorSelect.value = "";

            if (availabilityInfo) {
                availabilityInfo.textContent = "";
            }

        });

    }


    /* ================= CHATBOT ================= */

    const icon = document.getElementById("chatbot_icon");
    const box = document.getElementById("chatbot_box");
    const sendBtn = document.getElementById("send_btn");
    const input = document.getElementById("chat_input");
    const messages = document.getElementById("chat_messages");
    const micBtn = document.getElementById("mic_btn");

    if (!icon || !box) return;

    /* ---------------- OPEN CLOSE ---------------- */

    icon.onclick = function () {

        const isOpening = box.style.display === "none" || box.style.display === "";

        box.style.display = isOpening ? "block" : "none";

        if (isOpening && messages.innerHTML.trim() === "") {
            addMessage("Hello! How can I help you today?", "bot");
        }
    };


    /* ---------------- ADD MESSAGE ---------------- */

    function addMessage(text, sender) {

        const div = document.createElement("div");
        div.style.marginBottom = "8px";

        div.innerHTML =
            sender === "user"
            ? "<strong>You:</strong> " + text
            : "<strong>Bot:</strong> " + text;

        messages.appendChild(div);
        messages.scrollTop = messages.scrollHeight;
    }


    /* ---------------- SEND MESSAGE ---------------- */

    if (sendBtn && input) {

        sendBtn.onclick = function () {

            const text = input.value.trim();

            if (!text) return;

            addMessage(text, "user");
            input.value = "";

            fetch("/clinic/chat", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({
                    jsonrpc: "2.0",
                    method: "call",
                    params: {
                        message: text
                    },
                    id: 1
                })
            })
            .then(response => response.json())
            .then(data => {

                if (data.result && data.result.response) {
                    addMessage(data.result.response, "bot");
                } else {
                    addMessage("No response from server", "bot");
                }

            })
            .catch(error => {
                console.error(error);
                addMessage("Server error occurred", "bot");
            });

        };

        /* ENTER KEY */

        input.addEventListener("keypress", function(e){
            if(e.key === "Enter"){
                sendBtn.click();
            }
        });

    }


    /* ---------------- VOICE INPUT ---------------- */

    const SpeechRecognition =
        window.SpeechRecognition || window.webkitSpeechRecognition;

    if (SpeechRecognition && micBtn && input) {

        const recognition = new SpeechRecognition();

        recognition.lang = "en-US";
        recognition.continuous = false;

        micBtn.onclick = function () {
            recognition.start();
        };

        recognition.onresult = function (event) {
            input.value = event.results[0][0].transcript;
        };

    }

});

document.addEventListener("DOMContentLoaded", function () {

    const phoneInput = document.querySelector("#phone");

    if (phoneInput) {
        const iti = window.intlTelInput(phoneInput, {
            initialCountry: "in",
            separateDialCode: true,
        });

        const form = phoneInput.closest("form");

        form.addEventListener("submit", function () {
            document.getElementById("phone_full").value = iti.getNumber();
        });
    }

});

