t.script:
document.addEventListener("DOMContentLoaded", function () {

    const url = new URL(window.location.href);

    if (url.searchParams.get("success")) {
        url.searchParams.delete("success");
        window.history.replaceState({}, document.title, url.pathname);
    }

});
setTimeout(function(){
    const msg = document.querySelector(".alert-success");
    if(msg){
        msg.style.display = "none";
    }
}, 4000);

document.addEventListener("DOMContentLoaded", function () {
    /* ================= 1. DOCTOR FILTER (Mee existing code) ================= */
    const specializationSelect = document.querySelector("[name='specialization_id']");
    const doctorSelect = document.getElementById("doctor_select");
    const availabilityInfo = document.getElementById("availability_info");
    const dateInput = document.getElementById("appointment_date");
    const timeSlotSelect = document.getElementById("time_slot_select");

    // Hide doctors initially
    for (let option of doctorSelect.options) {
        if (option.value !== "") {
            option.style.display = "none";
        }
    }

    specializationSelect.addEventListener("change", function () {
        const selectedSpec = this.value;
        for (let option of doctorSelect.options) {
            if (option.value === "") continue;
            option.style.display = (option.dataset.spec === selectedSpec) ? "block" : "none";
        }
        doctorSelect.value = "";
        availabilityInfo.textContent = "";
        timeSlotSelect.innerHTML = '<option value="">Select date &amp; doctor first</option>';
    });

    /* ================= 2. TIME SLOT FETCH LOGIC ================= */
function fetchTimeSlots() {
    const doctorId = doctorSelect.value;
    const appointmentDate = dateInput.value;

    if (doctorId && appointmentDate) {
        fetch('/get_slots', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                jsonrpc: "2.0",
                params: { doctor_id: doctorId, date: appointmentDate }
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result) {
                timeSlotSelect.innerHTML = '<option value="">Select Time Slot</option>';
                data.result.forEach(slot => {
                    const option = document.createElement('option');
                    // Use slot.id for the value and slot.name for the text shown to the user
                    option.value = slot.id; 
                    option.textContent = slot.name; 
                    timeSlotSelect.appendChild(option);
                });
            }
        })
        .catch(error => console.error('Error fetching slots:', error));
    }
}

    // Doctor leda Date change ainappudu slots update avvali
    doctorSelect.addEventListener("change", fetchTimeSlots);
    dateInput.addEventListener("change", fetchTimeSlots);

});

